-- TEST_FIXTURE_DDL: an isolated instance of the actual CampusLibrary topic; not a product migration.
CREATE TABLE user (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, role VARCHAR(32) NOT NULL DEFAULT 'READER', active_loans INT NOT NULL DEFAULT 0, name VARCHAR(64) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL);
CREATE TABLE access_token (id CHAR(36) NOT NULL PRIMARY KEY, owner_id BIGINT NOT NULL, expires_at DATETIME(6) NOT NULL, CONSTRAINT fixture_access_owner FOREIGN KEY (owner_id) REFERENCES user(id));
CREATE TABLE refresh_token (id CHAR(36) NOT NULL PRIMARY KEY, owner_id BIGINT NOT NULL, used TINYINT(1) NOT NULL DEFAULT 0, expires_at DATETIME(6) NOT NULL, CONSTRAINT fixture_refresh_owner FOREIGN KEY (owner_id) REFERENCES user(id));
CREATE TABLE token_pair (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, access_token CHAR(36) NOT NULL, access_expires_at DATETIME(6) NOT NULL, refresh_token CHAR(36) NOT NULL, refresh_expires_at DATETIME(6) NOT NULL);
CREATE TABLE book (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, isbn VARCHAR(64) NOT NULL UNIQUE, title VARCHAR(64) NOT NULL, author VARCHAR(64) NOT NULL, publisher VARCHAR(64) NULL);
CREATE TABLE copy (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, barcode VARCHAR(64) NOT NULL UNIQUE, book_id BIGINT NOT NULL, status VARCHAR(32) NOT NULL DEFAULT 'AVAILABLE', CONSTRAINT fixture_copy_book FOREIGN KEY (book_id) REFERENCES book(id));
CREATE TABLE loan (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, reader_id BIGINT NOT NULL, copy_id BIGINT NOT NULL, borrowed_at DATETIME(6) NOT NULL, due_at DATETIME(6) NOT NULL, renewals INT NOT NULL DEFAULT 0, returned TINYINT(1) NOT NULL DEFAULT 0, returned_at DATETIME(6) NULL, CONSTRAINT fixture_loan_reader FOREIGN KEY (reader_id) REFERENCES user(id), CONSTRAINT fixture_loan_copy FOREIGN KEY (copy_id) REFERENCES copy(id));
